from __future__ import annotations
from nautilus_trader.common.actor import Actor from nautilus_trader.config import ActorConfig from nautilus_trader.model.data import Bar, Data
class SignalActorConfig(ActorConfig): pass
class SignalActor(Actor): def __init__(self, config: SignalActorConfig) -> None: super().__init__(config)
def on_bar(self, bar: Bar) -> None: # Compute signal from bar data (past only) signal = self._compute_signal(bar) # Publish for Strategy consumption self.publish_data(signal)
def _compute_signal(self, bar: Bar) -> Data: # Implementation here pass

from nautilus_trader.backtest.node import BacktestNode from nautilus_trader.backtest.config import ( BacktestRunConfig, BacktestEngineConfig, BacktestDataConfig, BacktestVenueConfig, )
config = BacktestRunConfig( engine=BacktestEngineConfig( strategies=[strategy_config], ), venues=[ BacktestVenueConfig( name="SIM", oms_type="NETTING", account_type="MARGIN", base_currency="USD", starting_balances=["100000 USD"], ), ], data=[ BacktestDataConfig( catalog_path="catalog", data_cls="nautilus_trader.model.data.Bar", instrument_id="XAU/USD.SIM", ), ], )
node = BacktestNode(configs=[config]) results = node.run()
